using System.Collections;
using UnityEngine;

/*
 * PortalSpawner
 * -------------
 * Our planets are generated by code (CubeSphereGenerator + PlanetNoise), so
 * we don't know the height of the ground before the game starts. That's why
 * we can't just place the portal by hand in the scene: it would float or be
 * under the ground.
 *
 * So this script places the portal at the start:
 *   1. wait one frame so the planet mesh and its Mesh Collider exist
 *   2. take the direction chosen in PlanetNoise (portalDirection). PlanetNoise
 *      also makes the ground flat around this point.
 *   3. shoot a ray from high in the sky down to the centre of the planet
 *   4. create the portal where the ray hits, tilted with the ground normal
 *   5. give the portal its destination (spawn point, puzzle to solve...)
 *
 * Start is a coroutine (IEnumerator) only to be able to wait one frame
 * with "yield return null".
 *
 * Things to know:
 *  - requiredPuzzle is found with FindAnyObjectByType, so it takes the FIRST
 *    Planet1Puzzle in the scene. If one day there are 2 puzzles, it may take
 *    the wrong one.
 *  - We only use col.Raycast (the planet collider) and not Physics.Raycast,
 *    so trees or rocks on top don't block the ray. But it means the portal
 *    could be placed inside a tree if PlanetScatter puts one there.
 */
public class PortalSpawner : MonoBehaviour
{
    public GameObject portalPrefab;
    public CubeSphereGenerator planetGenerator;
    public PlanetNoise planetNoise;

    [Tooltip("Raise (+) or lower (-) the portal if its pivot is not at its base")]
    public float heightOffset = 0f;

    [Header("Where the portal leads")]
    public Transform destinationSpawnPoint;
    public GravitySource destinationGravity;
    public bool requireAllEnemiesDead = false;

    IEnumerator Start()
    {
        if (portalPrefab == null || planetNoise == null || planetGenerator == null) yield break;

        yield return null;   // wait for the planet and its Mesh Collider to exist

        MeshCollider col = planetGenerator.GetComponent<MeshCollider>();
        if (col == null)
        {
            Debug.LogWarning("PortalSpawner: the planet has no Mesh Collider.", this);
            yield break;
        }

        Transform planet = planetGenerator.transform;

        // Direction of the portal, in world space (works even if the planet is moved or rotated)
        Vector3 worldDir = planet.TransformDirection(planetNoise.portalDirection.normalized);

        // Shoot a ray from far above the surface straight toward the planet centre
        // "far" = radius + max height of the noise + mountains + 20 m of margin,
        // so we are sure to start outside the planet.
        float far = planetGenerator.radius + planetNoise.height + planetNoise.mountainHeight + 20f;
        Ray ray = new Ray(planet.position + worldDir * far, -worldDir);

        if (!col.Raycast(ray, out RaycastHit hit, far * 2f))
        {
            Debug.LogWarning("PortalSpawner: the ray missed the planet.", this);
            yield break;
        }

        // Stand on the real ground and tilt with its normal
        Quaternion rot = Quaternion.FromToRotation(Vector3.up, hit.normal);
        Vector3 pos = hit.point + hit.normal * heightOffset;

        // The portal is a child of the planet, so it moves with it
        GameObject portal = Instantiate(portalPrefab, pos, rot, planet);

        // Give the settings to the portal script inside the prefab
        var travel = portal.GetComponentInChildren<InterplanetaryPortal>();
        if (travel != null)
        {
            travel.destinationSpawnPoint = destinationSpawnPoint;
            travel.destinationGravity = destinationGravity;
            travel.requiredPuzzle = FindAnyObjectByType<Planet1Puzzle>();   // sealed until Planet 1 is solved
            travel.requireAllEnemiesDead = requireAllEnemiesDead;
        }
        else
        {
            Debug.LogWarning("PortalSpawner: the portal prefab has no InterplanetaryPortal component.", portal);
        }
    }
}